<template><AsyncState :loading="loading" :error="error" @retry="$emit('list')"><main class="page"><PageHeader :title="t('nav.remote')"><template #primary><button data-action="refresh-remote" @click="$emit('list')">{{t('btn.refresh')}}</button></template></PageHeader><SectionCard :title="t('remote.create')"><label>{{t('remote.adapter')}}<select v-model="adapter"><option value="docker">{{t('remote.adapter_docker')}}</option><option value="ssh">{{t('remote.adapter_ssh')}}</option></select></label><template v-if="adapter==='docker'"><label>{{t('remote.image')}}<input v-model.trim="image" data-field="remote-image"></label></template><template v-else><label>{{t('remote.ssh_host')}}<input v-model.trim="host" data-field="remote-host"></label><label>{{t('remote.ssh_port')}}<input v-model.number="port" type="number" min="1" max="65535"></label><label>{{t('remote.ssh_user')}}<input v-model.trim="user"></label><label>{{t('remote.ssh_keypath')}}<input v-model.trim="keyPath"></label></template><button data-action="create-remote" :disabled="creating||(adapter==='docker'?!image:!host)" @click="create">{{t('remote.create_btn')}}</button></SectionCard><SectionCard :title="t('remote.instances')"><article v-for="inst in instances" :key="inst.id" :data-instance="inst.id"><h3>{{inst.id}} <StatusBadge :tone="inst.status==='running'?'success':'neutral'">{{inst.status}}</StatusBadge></h3><CopyableValue v-for="path in inst.addresses||[]" :key="path" :value="path" :copy-label="t('remote.copy_address')"/><div class="actions"><button v-if="inst.addresses?.[0]" data-action="copy-address" @click="$emit('copy-address',inst.addresses[0])">{{t('remote.copy_address')}}</button><ConfirmAction :title="t('remote.destroy_confirm')" :pending="!!operating[inst.id]?.destroy" @confirm="$emit('destroy',inst.adapter,inst.id)"><template #trigger><button data-action="destroy-remote" :disabled="!!operating[inst.id]?.destroy">{{t('remote.destroy_btn')}}</button></template></ConfirmAction></div><label>{{t('remote.exec_placeholder')}}<input v-model.trim="commands[inst.id]" data-field="remote-command" @keyup.enter="run(inst)"></label><button data-action="exec-remote" :disabled="!!operating[inst.id]?.exec||!commands[inst.id]" @click="run(inst)">{{t('btn.run')}}</button><CopyableValue v-if="outputs[inst.id]" :value="outputs[inst.id]" :max-length="120"/></article><p v-if="!instances.length">{{t('remote.no_instances')}}</p></SectionCard></main></AsyncState></template>
<script setup>import{reactive,ref}from'vue';import AsyncState from'../components/AsyncState.vue';import ConfirmAction from'../components/ConfirmAction.vue';import CopyableValue from'../components/CopyableValue.vue';import PageHeader from'../components/PageHeader.vue';import SectionCard from'../components/SectionCard.vue';import StatusBadge from'../components/StatusBadge.vue';const props=defineProps({t:{type:Function,required:true},instances:{type:Array,default:()=>[]},loading:Boolean,error:[String,Error],creating:Boolean,operating:{type:Object,default:()=>({})},outputs:{type:Object,default:()=>({})}});const emit=defineEmits(['list','create','copy-address','exec','destroy']);const adapter=ref('docker'),image=ref(''),host=ref(''),port=ref(22),user=ref('root'),keyPath=ref(''),commands=reactive({});const create=()=>emit('create',{adapter:adapter.value,image:image.value,sshHost:host.value,sshPort:port.value,sshUser:user.value,sshKeyPath:keyPath.value});const run=inst=>commands[inst.id]&&emit('exec',inst.adapter,inst.id,commands[inst.id]);</script><style scoped>.page{display:grid;gap:16px;min-width:0}article{display:grid;gap:8px;padding:12px;border:1px solid var(--xdev-border-subtle);overflow:hidden}label{display:grid;gap:4px}input,select{max-width:100%;box-sizing:border-box}.actions{display:flex;gap:8px;flex-wrap:wrap}</style>
